## ---- 10: Rate Floor Application  (qmd line 260) --------------------------------------

# Hard floor at zero
yield_paths_floored <- lapply(yield_paths, function(M) pmax(M, 0))

# Soft floor (smooth approximation)
soft_floor <- function(x, k = 100) log1p(exp(k * x)) / k
yield_paths_soft <- lapply(yield_paths, soft_floor)


## ---- 11: Scenario Mode (User Helper)  (qmd line 271) ---------------------------------

# Helper: deterministic shifted Prime paths (not in package — illustrative)
scenario_prime_paths <- function(base_path, shifts_bp = c(-50, -25, 0, 25, 50)) {
  n_months <- length(base_path)
  out <- matrix(NA_real_, nrow = length(shifts_bp), ncol = n_months)
  for (i in seq_along(shifts_bp)) {
    out[i, ] <- base_path + shifts_bp[i] / 10000
  }
  out
}

# oasr::extract_reference_rates pulls a chosen tenor from the rate-paths object
library(oasr)
prime_path <- extract_reference_rates(list(yield_paths = yield_paths),
                                      reference_key = "0.25")[1, ] + 0.03
scenarios  <- scenario_prime_paths(prime_path)
str(scenarios)


## ---- 12: Fan Chart Visualization  (qmd line 292) -------------------------------------

library(ggplot2)
library(dplyr)

ten_year <- yield_paths[["10"]]
fan_data <- apply(ten_year, 2, quantile,
                  probs = c(0.05, 0.25, 0.5, 0.75, 0.95)) %>%
  t() %>% as.data.frame() %>%
  # time grid has n_steps + 1 points, month 0 first
  mutate(month = seq_len(n()) - 1)

ggplot(fan_data, aes(x = month)) +
  geom_ribbon(aes(ymin = `5%`, ymax = `95%`), alpha = 0.2) +
  geom_ribbon(aes(ymin = `25%`, ymax = `75%`), alpha = 0.4) +
  geom_line(aes(y = `50%`)) +
  labs(x = "Month", y = "10Y Yield",
       title = "Fan chart: 10Y Treasury yield, simulated")


