# 10Y - 2Y spread across paths at horizon = 5 yrs
library(ggplot2)
spread_5y <- yield_paths[["10"]][, 60] - yield_paths[["2"]][, 60]
ggplot(data.frame(spread_bps = spread_5y * 10000), aes(spread_bps)) +
  geom_histogram(bins = 30, fill = "steelblue", colour = "white") +
  labs(title = "10Y-2Y spread distribution at 5 years",
       x = "Spread (bps)", y = "Count") +
  theme_minimal()


